// Compute cart total
export function computeTotal(items: LineItem[], discountMultiplier: number = 1.0, taxRate: number = 0.0): number {
  const subtotal = items.reduce((acc, item) => acc + item.price * item.quantity, 0)
  return subtotal * discountMultiplier * (1 + taxRate)
}
